{"cards": [{"node_code": "N_39c14b932697992b", "definition": "基于线弹性假设研究裂纹尖端应力场奇异性及能量释放率的断裂力学分支，核心参数为应力强度因子K。", "boundary": "适用于裂纹尖端塑性区尺寸远小于裂纹长度及构件特征尺寸的工况。聚焦于K因子计算、I/II/III型裂纹模式及线弹性断裂判据。若塑性区显著或涉及大变形，应归入弹塑性断裂力学节点。", "includes": ["应力强度因子K的定义、计算及叠加原理", "I型、II型、III型裂纹的线弹性解", "线弹性断裂韧度KIC及临界应力强度因子分析"], "excludes": ["裂纹尖端存在显著塑性变形时的力学行为（归弹塑性断裂力学）", "循环载荷下的疲劳裂纹扩展速率（归疲劳力学）"], "sibling_distinctions": [{"other_code": "N_291d73c054a7900e", "rule": "本节点假设材料处于线弹性状态，使用K因子；弹塑性节点处理裂纹尖端塑性区不可忽略的情况，使用J积分或CTOD。"}, {"other_code": "N_78a076a610730e16", "rule": "本节点侧重断裂发生的临界条件与判据；裂纹扩展节点侧重裂纹长度随时间或载荷变化的动力学过程及速率。"}], "cross_boundary_rule": "当塑性区尺寸满足小尺度屈服条件时归本节点；若需考虑塑性修正或大尺度屈服，归弹塑性断裂力学节点。"}, {"node_code": "N_291d73c054a7900e", "definition": "研究裂纹尖端存在显著塑性变形时应力应变场及断裂行为的力学分支，涵盖J积分、CTOD及弹塑性本构模型。", "boundary": "适用于裂纹尖端塑性区尺寸不可忽略、材料发生屈服或大变形的情形。聚焦于弹塑性断裂参数（J、CTOD、CMOD）的定义、计算及与线弹性参数的关联。纯线弹性小尺度屈服问题不作为主挂载。", "includes": ["J积分、裂纹尖端张开位移（CTOD）及张开角（CCPA）", "弹塑性断裂韧度JIC及临界CTOD值", "裂纹尖端弹塑性场分析及有限元数值模拟方法"], "excludes": ["裂纹尖端完全处于线弹性状态的问题（归线弹性断裂力学）", "纯材料本构关系研究而不涉及裂纹尖端场（归固体力学或材料节点）"], "sibling_distinctions": [{"other_code": "N_39c14b932697992b", "rule": "本节点处理塑性区显著的情况，使用J/CTOD等参数；线弹性节点处理小尺度屈服，使用K因子。"}, {"other_code": "N_78a076a610730e16", "rule": "本节点侧重断裂发生的临界弹塑性状态；裂纹扩展节点侧重裂纹在弹塑性条件下的扩展速率与路径。"}], "cross_boundary_rule": "若问题涉及裂纹尖端塑性区大小与裂纹长度的比值判断，需结合线弹性与弹塑性节点；若明确为大尺度屈服，主挂载本节点。"}, {"node_code": "N_78a076a610730e16", "definition": "研究裂纹在载荷作用下长度变化规律、扩展速率及材料抵抗裂纹扩展能力的力学分支，涵盖静态与动态扩展。", "boundary": "聚焦于裂纹扩展的动力学过程、扩展速率（da/dN或da/dt）及断裂韧度（KIC, JIC等）的测定与应用。包括裂纹偏转、分叉及动态断裂。纯裂纹尖端静态应力场分析不作为主挂载，除非用于确定扩展判据。", "includes": ["裂纹扩展速率曲线（Paris公式等）及影响因素", "静态与动态断裂韧度的定义、测试及工程应用", "裂纹扩展路径、偏转、分叉及动态断裂行为"], "excludes": ["纯裂纹萌生前的损伤累积过程（归疲劳力学或损伤力学）", "纯裂纹尖端静态应力强度因子计算而不涉及扩展（归线弹性或弹塑性断裂力学）"], "sibling_distinctions": [{"other_code": "N_39c14b932697992b", "rule": "本节点关注裂纹“动”的过程（扩展、速率）；线弹性节点关注裂纹“静”的临界状态（K因子、KIC）。"}, {"other_code": "N_291d73c054a7900e", "rule": "本节点关注裂纹扩展行为及韧度指标；弹塑性节点关注裂纹尖端的弹塑性场参数（J, CTOD）及其临界值。"}], "cross_boundary_rule": "涉及疲劳裂纹扩展时，若侧重扩展速率与寿命预测归本节点或疲劳力学节点（视具体侧重，通常速率归本节点，寿命归疲劳）；若侧重扩展时的尖端场参数归弹塑性节点。"}]}
